<p>
<script>
    function checkQ1() {
        const options = document.getElementsByName('q1');
        let selectedValue = null;
        for (const option of options) { if (option.checked) selectedValue = option.value; }

        const feedbackDiv = document.getElementById('feedbackQ1');
        feedbackDiv.style.display = 'block';

        if (!selectedValue) {
            feedbackDiv.innerHTML = "⚠️ Por favor, selecciona una opción antes de comprobar.";
            feedbackDiv.style.backgroundColor = "#fff3cd"; feedbackDiv.style.color = "#856404"; return;
        }

        switch(selectedValue) {
            case 'A':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Recuerda que en los movimientos rígidos la forma nunca se deforma, por lo tanto, los ángulos se conservan idénticos.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
            case 'B':
                feedbackDiv.innerHTML = "✅ <b>¡Correcto!</b> Esta es la clave de la isometría: al trasladar, rotar o reflejar, los lados y los ángulos mantienen su longitud y medida exacta.";
                feedbackDiv.style.backgroundColor = "#d4edda"; feedbackDiv.style.color = "#155724"; break;
            case 'C':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Si el tamaño aumenta, estaríamos hablando de una ampliación u homotecia, lo cual no es un movimiento rígido.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
            case 'D':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Las figuras resultantes de un movimiento rígido siempre son congruentes (tienen la misma forma y tamaño) a las originales.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
        }
    }

    function checkQ2() {
        const options = document.getElementsByName('q2');
        let selectedValue = null;
        for (const option of options) { if (option.checked) selectedValue = option.value; }

        const feedbackDiv = document.getElementById('feedbackQ2');
        feedbackDiv.style.display = 'block';

        if (!selectedValue) {
            feedbackDiv.innerHTML = "⚠️ Por favor, selecciona una opción antes de comprobar.";
            feedbackDiv.style.backgroundColor = "#fff3cd"; feedbackDiv.style.color = "#856404"; return;
        }

        switch(selectedValue) {
            case 'A':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Si solo la trasladas hacia la derecha, la flecha seguirá apuntando hacia la izquierda. Solo cambió de lugar, no de dirección.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
            case 'B':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Una rotación de 360° es dar una vuelta completa, por lo que la señal quedaría exactamente igual que al principio.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
            case 'C':
                feedbackDiv.innerHTML = "✅ <b>¡Excelente!</b> Al usar una reflexión con un eje vertical (como un espejo puesto de pie al lado de la señal), la flecha que apuntaba a la izquierda ahora apuntará a la derecha.";
                feedbackDiv.style.backgroundColor = "#d4edda"; feedbackDiv.style.color = "#155724"; break;
            case 'D':
                feedbackDiv.innerHTML = "❌ <b>Incorrecto.</b> Un eje de reflexión horizontal (como un espejo en el suelo) haría que la señal quedara de cabeza, pero seguiría apuntando hacia la misma dirección.";
                feedbackDiv.style.backgroundColor = "#f8d7da"; feedbackDiv.style.color = "#721c24"; break;
        }
    }
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
